item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {buildDebtServiceSchedule, calculateAllInCost, calculateCovenantHeadroom, calculateLeverage, calculateProFormaPosition, maturityConcentration} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `compare-refinancing-before-after` (v4, after the second independent
  9	 * review). Every alternative is shown before and after with the same objects: gross and net debt by
 10	 * the contractual components, leverage on a declared EBITDA, headroom only against a resolved and
 11	 * comparable limit, concentration by the schedule's own periods (safra years with their end dates,
 12	 * new principal placed by date), principal cover per period when cash generation is declared, and
 13	 * the all-in cost of the new debt including exit premiums and fees paid from cash. The cost of the
 14	 * existing debt is a different basis and is never ranked against the new debt's all-in. A retired
 15	 * series without a priced exit blocks its alternative; a ranking needs a declared discriminator.
 16	 */
 17	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 18	const rate = z.string().regex(/^\d+(\.\d+)?$/);
 19	const nonEmpty = z.string().trim().min(1);
 20	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 21	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 22	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 23	type Anchor = z.infer<typeof anchorSchema>;
 24	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 25	
 26	export const alternativeSchema = z.object({
 27	  id: z.string().regex(/^[a-z][a-z0-9_-]*$/),
 28	  label: nonEmpty,
 29	  newDebt: z.object({amount: nonNegative, annualRate: rate, termMonths: z.number().int().positive(), graceMonths: z.number().int().nonnegative(), format: z.enum(["sac", "price", "bullet", "balloon"]), upfrontFeeRate: rate, disbursementDate: isoDate, origin: nonEmpty, anchor: anchorSchema}).strict().nullable(),
 30	  /** Series retired, each with its priced exit (from the exit-cost executor) and its anchor; a null price blocks the alternative. */
 31	  retired: z.array(z.object({seriesId: nonEmpty, principal: nonNegative, exitPremium: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(), maturityPeriod: nonEmpty, anchor: anchorSchema}).strict()).default([]),
 32	  /** Other cash costs of the alternative (advisory, registry), with their anchor when above zero. */
 33	  feesPaidFromCash: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
 34	  /** Terms the alternative still lacks; carried, never filled. */
 35	  uncoveredTerms: z.array(nonEmpty).default([]),
 36	}).strict();
 37	
 38	const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
 39	
 40	export const beforeAfterInputSchema = z.object({
 41	  referenceDate: isoDate,
 42	  unit: unitSchema,
 43	  /** Where the source states the unit; its note must name that unit, so a relabelled scale is refused. */
 44	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
 45	  before: z.object({
 46	    grossDebt: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 47	    unrestrictedCash: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 48	    derivativeLiabilities: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 49	    derivativeAssets: z.object({value: nonNegative, anchor: anchorSchema}).strict(),
 50	    ltmEbitda: z.object({value: nonNegative, definitionKey: nonEmpty, basis: z.enum(["company_opened", "implied_from_reported_index", "derived_proxy"]), anchor: anchorSchema}).strict().nullable(),
 51	    /** The schedule in the ledger's own periods; `endsAt` places new principal by date, null marks the open-ended bucket. */
 52	    schedule: z.array(z.object({period: nonEmpty, amount: z.string().regex(/^-?\d+(\.\d+)?$/), endsAt: isoDate.nullable(), kind: z.enum(["maturity", "adjustment"]).default("maturity")}).strict()).min(1),
 53	    /** Cost of the existing debt, on its own basis; never the same basis as a new debt's all-in. */
 54	    costOfExistingDebt: z.object({weightedAverageRate: rate, basis: nonEmpty, anchor: anchorSchema}).strict(),
 55	    /** Cash generation per period when the base declares it; without it the cover per period is insufficient evidence. */
 56	    cfadsByPeriod: z.record(nonEmpty, nonNegative).nullable().default(null),
 57	  }).strict(),
 58	  covenant: z.object({
 59	    instrument: nonEmpty,
 60	    limit: rate,
 61	    direction: z.enum(["maximum", "minimum"]),
 62	    /** When the indenture measures the index; a reading at the reference date is interim unless it is a measurement date. */
 63	    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), nextDate: isoDate}).strict(),
 64	    /** The tier the limit belongs to and the condition that makes it applicable, when the indenture steps the limit. */
 65	    tier: z.object({applicable: z.boolean(), condition: nonEmpty}).strict().nullable(),
 66	    state: z.enum(["resolved", "insufficient_evidence"]),
 67	    comparability: z.enum(["comparable", "conditional", "not_comparable"]),
 68	    anchor: anchorSchema,
 69	  }).strict(),
 70	  alternatives: z.array(alternativeSchema).min(1),
 71	  /** The declared discriminator; without one there is no ranking. all_in_cost ranks only the new debts among themselves. */
 72	  ranking: z.object({discriminator: z.enum(["headroom", "all_in_cost", "peak_concentration", "peak_amount", "net_debt"]), rationale: nonEmpty}).strict().nullable().default(null),
 73	  wallThreshold: z.object({share: nonNegative, policyKey: nonEmpty, policyVersion: nonEmpty}).strict(),
 74	}).strict().superRefine((input, context) => {
 75	  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
 76	  if (input.covenant.measurement.nextDate <= input.referenceDate) context.addIssue({code: "custom", path: ["covenant", "measurement"], message: "the next measurement date must follow the reference date"});
 77	  const periods = new Set<string>();
 78	  const sorted = [...input.before.schedule].sort(scheduleOrder);
 79	  sorted.forEach((entry, index) => {
 80	    if (periods.has(entry.period)) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `duplicate period ${entry.period}`});
 81	    periods.add(entry.period);
 82	    if (entry.endsAt !== null && entry.endsAt <= input.referenceDate) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `period ${entry.period} ends on or before the reference date`});
 83	    if (entry.kind === "maturity" && entry.amount.startsWith("-")) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `period ${entry.period} carries a negative amount; only an adjustment row may`});
 84	    if (entry.kind === "adjustment" && entry.endsAt !== null) context.addIssue({code: "custom", path: ["before", "schedule", index], message: `adjustment ${entry.period} belongs to no period and cannot end on a date`});
 85	  });
 86	  if (sorted.filter((entry) => entry.endsAt === null && entry.kind === "maturity").length > 1) context.addIssue({code: "custom", path: ["before", "schedule"], message: "at most one open-ended bucket"});
 87	  const ids = new Set<string>();
 88	  input.alternatives.forEach((alternative, index) => {
 89	    if (ids.has(alternative.id)) context.addIssue({code: "custom", path: ["alternatives", index], message: `duplicate alternative ${alternative.id}`});
 90	    ids.add(alternative.id);
 91	    const series = new Set<string>();
 92	    alternative.retired.forEach((entry, position) => {
 93	      if (series.has(entry.seriesId)) context.addIssue({code: "custom", path: ["alternatives", index, "retired", position], message: `${alternative.id}: series ${entry.seriesId} retired twice`});
 94	      series.add(entry.seriesId);
 95	      if (!periods.has(entry.maturityPeriod) || input.before.schedule.find((row) => row.period === entry.maturityPeriod)?.kind === "adjustment") context.addIssue({code: "custom", path: ["alternatives", index, "retired", position], message: `${alternative.id}: ${entry.seriesId} matures in ${entry.maturityPeriod}, which is not a period of the schedule`});
 96	    });
 97	    if (alternative.newDebt && alternative.newDebt.disbursementDate < input.referenceDate) context.addIssue({code: "custom", path: ["alternatives", index, "newDebt", "disbursementDate"], message: `${alternative.id}: the new debt is disbursed before the reference date`});
 98	    if (alternative.newDebt && alternative.newDebt.graceMonths >= alternative.newDebt.termMonths) context.addIssue({code: "custom", path: ["alternatives", index, "newDebt", "graceMonths"], message: `${alternative.id}: grace must be shorter than the term`});
 99	  });
100	});
101	export type BeforeAfterInput = z.input<typeof beforeAfterInputSchema>;
102	
103	type Calculation = {id: string; alternative: string; formula: string; operands: Record<string, string>; result: string; unit: string};
104	type Snapshot = {
105	  gross_debt: string; unrestricted_cash: string; net_debt: string; contractual_net_debt: string;
106	  leverage: {value: string; ebitda_definition: string; ebitda_basis: string} | null;
107	  headroom: {absolute: string; within_limit: boolean; reading: "interim" | "measurement_date"; note: string} | null;
108	  peak: {period: string; amount: string; share_of_gross: string} | null;
109	  cost: {value: string; basis: string; comparable_with_new_debt: boolean};
110	  anchors: Record<string, Anchor>;
111	};
112	
113	export type BeforeAfterOutput = {
114	  schema_version: "method.compare-refinancing-before-after.v4";
115	  reference_date: string;
116	  unit: string;
117	  state: "compared" | "blocked";
118	  block_reasons: string[];
119	  wall_threshold: {share: string; policyKey: string; policyVersion: string};
120	  /** Rows of the ledger's schedule that belong to no period (transaction costs); they reconcile the schedule to the gross debt and never enter the concentration. */
121	  schedule_adjustments: Array<{id: string; amount: string}>;
122	  before: Snapshot;
123	  alternatives: Array<{
124	    id: string; label: string; state: "compared" | "blocked"; block_reasons: string[];
125	    after: Snapshot | null;
126	    exit_cost: {value: string; anchors: Anchor[]} | null;
127	    concentration: Array<{period: string; existing: string; proposed: string; consolidated: string; share_of_gross: string; is_wall: boolean; principal_coverage: string | null}> | null;
128	    new_debt_service: {peak_debt_service: string; total_interest: string; weighted_average_life_months: string; all_in_cost: string; anchor: Anchor} | null;
129	    uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
130	  }>;
131	  /** `value` is the economic figure of the discriminator (a share, a cost, an amount); `score` is the internal ordering key (higher is better). */
132	  ranking: {discriminator: string; rationale: string; order: Array<{id: string; value: string; score: string; reason: string}>} | null;
133	  unsupported: string[];
134	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
135	};
136	
137	const d = (value: Decimal.Value) => new Decimal(value);
138	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
139	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
140	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
141	const addMonths = (isoDate: string, months: number) => { const date = new Date(`${isoDate}T00:00:00Z`); date.setUTCMonth(date.getUTCMonth() + months); return date.toISOString().slice(0, 10); };
142	
143	const scheduleOrder = (a: {period: string; endsAt: string | null; kind: string}, b: {period: string; endsAt: string | null; kind: string}) => (a.kind !== b.kind ? (a.kind === "adjustment" ? 1 : -1) : a.endsAt === null && b.endsAt === null ? compare(a.period, b.period) : a.endsAt === null ? 1 : b.endsAt === null ? -1 : compare(a.endsAt, b.endsAt) || compare(a.period, b.period));
144	function canonical(input: z.infer<typeof beforeAfterInputSchema>) {
145	  return {
146	    ...input,
147	    before: {...input.before, schedule: [...input.before.schedule].sort(scheduleOrder)},
148	    alternatives: [...input.alternatives].sort((a, b) => compare(a.id, b.id)).map((alternative) => ({...alternative, retired: [...alternative.retired].sort((a, b) => compare(a.seriesId, b.seriesId)), uncoveredTerms: [...alternative.uncoveredTerms].sort(compare)})),
149	  };
150	}
151	
152	export function compareRefinancingBeforeAfter(raw: BeforeAfterInput): BeforeAfterOutput {
153	  const input = canonical(beforeAfterInputSchema.parse(raw));
154	  const calculations: Calculation[] = [];
155	  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
156	  const unsupported: string[] = [];
157	  const blockReasons: string[] = [];
158	  const threshold = d(input.wallThreshold.share);
159	  const canMeasureHeadroom = input.covenant.state === "resolved" && input.covenant.comparability === "comparable";
160	  if (!canMeasureHeadroom) unsupported.push(`headroom is not measured: covenant limit ${input.covenant.state}, comparability ${input.covenant.comparability}`);
161	  const ebitda = input.before.ltmEbitda;
162	  if (!ebitda) unsupported.push("leverage is not measured: no EBITDA with a definition in the base");
163	  else if (d(ebitda.value).lte(0)) unsupported.push("leverage is not measured: the EBITDA in the base is zero or negative");
164	  if (!input.before.cfadsByPeriod) unsupported.push("principal cover per period is not measured: no cash generation per period in the base");
165	  const scheduleTotal = input.before.schedule.reduce((sum, entry) => sum.plus(entry.amount), d(0));
166	  if (!scheduleTotal.eq(input.before.grossDebt.value)) blockReasons.push(`the schedule sums to ${out(scheduleTotal)} and the gross debt is ${input.before.grossDebt.value}; the ledger did not reconcile them`);
167	  const maturities = input.before.schedule.filter((entry) => entry.kind === "maturity");
168	  const adjustments = input.before.schedule.filter((entry) => entry.kind === "adjustment");
169	  const periodOf = (date: string): string | null => {
170	    const dated = maturities.filter((entry) => entry.endsAt !== null);
171	    const hit = dated.find((entry) => date <= entry.endsAt!);
172	    if (hit) return hit.period;
173	    const open = maturities.find((entry) => entry.endsAt === null);
174	    return open ? open.period : null;
175	  };
176	
177	  const snapshot = (label: string, grossDebt: Decimal, cash: Decimal, cost: Snapshot["cost"], consolidated: Record<string, Decimal.Value>, anchors: Record<string, Anchor>): Snapshot => {
178	    const contractual = grossDebt.plus(input.before.derivativeLiabilities.value).minus(input.before.derivativeAssets.value).minus(cash);
179	    record({id: "financial.debt_views:contractual", alternative: label, formula: "grossDebt + derivativeLiabilities - derivativeAssets - unrestrictedCash", operands: {grossDebt: out(grossDebt), derivativeLiabilities: input.before.derivativeLiabilities.value, derivativeAssets: input.before.derivativeAssets.value, unrestrictedCash: out(cash)}, result: out(contractual)});
180	    let leverage: Snapshot["leverage"] = null;
181	    if (ebitda && d(ebitda.value).gt(0)) {
182	      const result = calculateLeverage(out(contractual), ebitda.value);
183	      record({id: "financial.net_leverage", alternative: label, formula: "contractualNetDebt / ltmEbitda", operands: {contractualNetDebt: out(contractual), ltmEbitda: ebitda.value, ebitdaBasis: ebitda.basis}, result: result.value}, "x");
184	      leverage = {value: result.value, ebitda_definition: ebitda.definitionKey, ebitda_basis: ebitda.basis};
185	    }
186	    let headroom: Snapshot["headroom"] = null;
187	    if (leverage && canMeasureHeadroom) {
188	      const result = calculateCovenantHeadroom({actual: leverage.value, limit: input.covenant.limit, direction: input.covenant.direction});
189	      record({id: "structure.covenant_headroom", alternative: label, formula: input.covenant.direction === "maximum" ? "limit - actual" : "actual - limit", operands: {actual: leverage.value, limit: input.covenant.limit}, result: result.absolute}, "x");
190	      const onDate = input.covenant.measurement.nextDate === input.referenceDate;
191	      headroom = {absolute: result.absolute, within_limit: result.passes, reading: onDate ? "measurement_date" : "interim", note: onDate ? `measured on the measurement date of ${input.covenant.instrument}` : `interim reading at ${input.referenceDate}; ${input.covenant.instrument} measures ${input.covenant.measurement.frequency}ly, next on ${input.covenant.measurement.nextDate}; neither a breach nor a compliance`};
192	    }
193	    const concentration = maturityConcentration({existing: consolidated, proposed: {}});
194	    const peak = concentration.peak && grossDebt.gt(0) ? {period: concentration.peak.period, amount: concentration.peak.consolidated, share_of_gross: out(d(concentration.peak.consolidated).div(grossDebt))} : null;
195	    if (peak) record({id: "structure.maturity_concentration:peak", alternative: label, formula: "peak / grossDebt", operands: {peak: peak.amount, grossDebt: out(grossDebt)}, result: peak.share_of_gross}, "x");
196	    return {gross_debt: out(grossDebt), unrestricted_cash: out(cash), net_debt: out(grossDebt.minus(cash)), contractual_net_debt: out(contractual), leverage, headroom, peak, cost, anchors};
197	  };
198	
199	  const beforeSchedule = Object.fromEntries(maturities.map((entry) => [entry.period, entry.amount]));
200	  const before = snapshot("before", d(input.before.grossDebt.value), d(input.before.unrestrictedCash.value), {value: input.before.costOfExistingDebt.weightedAverageRate, basis: input.before.costOfExistingDebt.basis, comparable_with_new_debt: false}, beforeSchedule, {grossDebt: input.before.grossDebt.anchor, unrestrictedCash: input.before.unrestrictedCash.anchor, derivativeLiabilities: input.before.derivativeLiabilities.anchor, derivativeAssets: input.before.derivativeAssets.anchor, ...(ebitda ? {ltmEbitda: ebitda.anchor} : {}), cost: input.before.costOfExistingDebt.anchor});
201	
202	  const alternatives = input.alternatives.map((alternative): BeforeAfterOutput["alternatives"][number] => {
203	    const reasons: string[] = [];
204	    const uncovered: BeforeAfterOutput["alternatives"][number]["uncovered_terms"] = alternative.uncoveredTerms.map((term) => ({id: term, state: "insufficient_evidence" as const, reason: `the alternative lacks ${term}; carried as a gap, not filled`}));
205	    const unpriced = alternative.retired.filter((series) => series.exitPremium === null);
206	    if (unpriced.length > 0) reasons.push(`exit cost is not priced for ${unpriced.map((series) => series.seriesId).join(", ")}; the alternative cannot be compared`);
207	    if (reasons.length > 0 || blockReasons.length > 0) return {id: alternative.id, label: alternative.label, state: "blocked", block_reasons: [...blockReasons, ...reasons], after: null, exit_cost: null, concentration: null, new_debt_service: null, uncovered_terms: uncovered};
208	
209	    const retiredPrincipal = alternative.retired.reduce((sum, series) => sum.plus(series.principal), d(0));
210	    const exitCost = alternative.retired.reduce((sum, series) => sum.plus(series.exitPremium!.value), d(0));
211	    const fees = alternative.feesPaidFromCash ? d(alternative.feesPaidFromCash.value) : d(0);
212	    const newAmount = alternative.newDebt ? d(alternative.newDebt.amount) : d(0);
213	    const upfrontFees = alternative.newDebt ? newAmount.times(alternative.newDebt.upfrontFeeRate) : d(0);
214	    const proForma = calculateProFormaPosition({grossDebt: input.before.grossDebt.value, unrestrictedCash: input.before.unrestrictedCash.value, newDebt: out(newAmount), refinancedDebt: out(retiredPrincipal), feesPaidFromCash: out(fees.plus(exitCost).plus(upfrontFees)), cashContribution: "0"});
215	    record({id: "operation.pro_forma_position", alternative: alternative.id, formula: "grossDebt + newDebt - retired ; cash - exitCost - upfrontFees - feesPaidFromCash", operands: {newDebt: out(newAmount), refinancedDebt: out(retiredPrincipal), exitCost: out(exitCost), upfrontFees: out(upfrontFees), feesPaidFromCash: out(fees)}, result: proForma.grossDebt});
216	
217	    // Schedule after: retired series leave their periods; the new principal lands in the period that holds its payment date.
218	    const existing: Record<string, Decimal> = Object.fromEntries(maturities.map((entry) => [entry.period, d(entry.amount)]));
219	    for (const series of alternative.retired) {
220	      if (existing[series.maturityPeriod]!.lt(series.principal)) reasons.push(`${series.seriesId}: the period ${series.maturityPeriod} holds ${out(existing[series.maturityPeriod]!)} and cannot lose ${series.principal}`);
221	      existing[series.maturityPeriod] = existing[series.maturityPeriod]!.minus(series.principal);
222	    }
223	    if (reasons.length > 0) return {id: alternative.id, label: alternative.label, state: "blocked", block_reasons: reasons, after: null, exit_cost: null, concentration: null, new_debt_service: null, uncovered_terms: uncovered};
224	    const proposed: Record<string, Decimal> = {};
225	    let newDebtService: BeforeAfterOutput["alternatives"][number]["new_debt_service"] = null;
226	    let cost: Snapshot["cost"] = {value: input.before.costOfExistingDebt.weightedAverageRate, basis: `${input.before.costOfExistingDebt.basis}; no new debt`, comparable_with_new_debt: false};
227	    if (alternative.newDebt) {
228	      const schedule = buildDebtServiceSchedule({amount: alternative.newDebt.amount, annualRate: alternative.newDebt.annualRate, rateConvention: "effective_annual", termMonths: alternative.newDebt.termMonths, graceMonths: alternative.newDebt.graceMonths, graceInterest: "paid", format: alternative.newDebt.format});
229	      record({id: "structure.debt_service_schedule", alternative: alternative.id, formula: `${alternative.newDebt.format}, ${alternative.newDebt.termMonths} months, ${alternative.newDebt.graceMonths} of grace`, operands: {amount: alternative.newDebt.amount, annualRate: alternative.newDebt.annualRate, disbursementDate: alternative.newDebt.disbursementDate}, result: schedule.totalDebtService});
230	      for (const row of schedule.rows) {
231	        if (d(row.principal).isZero()) continue;
232	        const date = addMonths(alternative.newDebt.disbursementDate, row.period);
233	        const key = periodOf(date);
234	        if (key === null) { reasons.push(`the new debt pays principal on ${date}, beyond the last dated period, and the schedule has no open-ended bucket to hold it`); break; }
235	        proposed[key] = (proposed[key] ?? d(0)).plus(row.principal);
236	      }
237	      if (reasons.length > 0) return {id: alternative.id, label: alternative.label, state: "blocked", block_reasons: reasons, after: null, exit_cost: null, concentration: null, new_debt_service: null, uncovered_terms: uncovered};
238	      const termYears = d(alternative.newDebt.termMonths).div(12);
239	      const allIn = calculateAllInCost(alternative.newDebt.annualRate, d(alternative.newDebt.upfrontFeeRate).plus(newAmount.gt(0) ? exitCost.plus(fees).div(newAmount) : 0).toFixed(), termYears.toFixed());
240	      record({id: "financial.all_in_cost", alternative: alternative.id, formula: "annualRate + (upfrontFeeRate + (exitCost + feesPaidFromCash) / amount) / termYears", operands: {annualRate: alternative.newDebt.annualRate, upfrontFeeRate: alternative.newDebt.upfrontFeeRate, exitCost: out(exitCost), feesPaidFromCash: out(fees), amount: out(newAmount), termYears: termYears.toFixed()}, result: allIn.value}, "x");
241	      newDebtService = {peak_debt_service: schedule.peakDebtService, total_interest: schedule.totalInterest, weighted_average_life_months: schedule.weightedAverageLifeMonths, all_in_cost: allIn.value, anchor: alternative.newDebt.anchor};
242	      cost = {value: allIn.value, basis: "all-in of the new debt: coupon plus upfront fee, exit premiums and cash fees amortized over the term", comparable_with_new_debt: true};
243	    }
244	    const consolidated = Object.fromEntries(maturities.map((entry) => [entry.period, existing[entry.period]!.plus(proposed[entry.period] ?? 0)]));
245	    const grossAfter = d(proForma.grossDebt);
246	    const rows = maturities.map((entry) => {
247	      const total = consolidated[entry.period]!;
248	      const share = grossAfter.gt(0) ? total.div(grossAfter) : d(0);
249	      const cfads = input.before.cfadsByPeriod?.[entry.period];
